interface.signature:
GET /api/v1/admin/company/settings
Response: { "data": Company }
Company fields: id, name, taxCode, address, logoUrl, contactEmail, contactPhone, fiscalYearStart

PUT /api/v1/admin/company/settings
Content-Type: multipart/form-data
Request: { "payload": UpdateCompanySettingsRequest, "logo": MultipartFile (optional) }
Response: { "data": Company }
